package mapper;import entity.LoaiRang;import java.sql.ResultSet;import java.sql.SQLException;public class LoaiRangMapper implements RowMapper<LoaiRang> {    @Override    public LoaiRang mapper(ResultSet rs) {        try {            String maLoaiRang = rs.getString("maLoaiRang");            String tenLoaiRang = rs.getString("tenLoaiRang");            return new LoaiRang(maLoaiRang, tenLoaiRang);        } catch (SQLException e) {            return null;        }    }}